#!/usr/bin/env python3
"""Turn the raw `claude -p --output-format json` result into triage.json + triage.md.

Usage: render-triage.py RAW_JSON OUT_DIR
"""
import json, os, sys

raw = json.load(open(sys.argv[1]))
out = sys.argv[2]
t = raw.get("structured_output")
if isinstance(t, str):
    t = json.loads(t)
if not t:
    md = "### 🤖 AI triage\n\nThe agent returned no structured verdict. See the job log.\n"
    open(os.path.join(out, "triage.md"), "w").write(md)
    print(md)
    sys.exit(0)

json.dump(t, open(os.path.join(out, "triage.json"), "w"), indent=2)

badge = {"regression": "🔴 regression", "test_defect": "🟠 test defect", "needs_server": "🔵 needs server",
         "environment": "⚙️ environment", "flaky": "🟡 flaky", "unknown": "⚪ unknown"}
md = ["### 🤖 AI triage", "", t["summary"], "",
      "| Test | Verdict | Confidence | Caused by this change |", "|---|---|---|---|"]
for f in t["failures"]:
    md.append(f"| `{f['test']}` | {badge.get(f['category'], f['category'])} | {f['confidence']} | "
              f"{'yes' if f.get('caused_by_change') else 'no'} |")
md.append("")
for f in t["failures"]:
    md += [f"<details><summary><code>{f['test']}</code> — {f['root_cause'][:120]}</summary>", "",
           f"**Root cause:** {f['root_cause']}", "", "**Evidence:**"]
    md += [f"- {e}" for e in f["evidence"]] or ["- (none)"]
    md += ["", f"**Suggested action:** {f['suggested_action']}", "", "</details>", ""]
cost = raw.get("total_cost_usd")
md.append(f"<sub>Generated by Claude Code (headless, read-only tools){f' · cost ${cost:.2f}' if cost else ''}. "
          "Verify before acting.</sub>")
open(os.path.join(out, "triage.md"), "w").write("\n".join(md) + "\n")
print("\n".join(md))
